#include "CaptureServer.h"
#include "PrintParser.h"
bool CaptureServer::begin(uint16_t port,CaptureStorage* storage){storage_=storage;server_=new WiFiServer(port);server_->begin();server_->setNoDelay(true);buffer_.reserve(65536);return true;}
void CaptureServer::finish(){if(buffer_.size()){CaptureRecord r;r.id=String((uint32_t)ESP.getEfuseMac(),HEX)+"-"+String(millis(),HEX)+"-"+String(accepted_);r.ip=client_.remoteIP().toString();r.port=client_.remotePort();r.timestamp=time(nullptr);auto p=PrintParser::parse(buffer_.data(),buffer_.size());r.format=p.format;r.text=p.text.substring(0,512);if(!storage_->append(r,buffer_.data(),buffer_.size()))errors_++;}client_.stop();buffer_.clear();active_=false;}
void CaptureServer::tick(){if(!server_)return;if(!active_){WiFiClient next=server_->available();if(next){client_=next;active_=true;opened_=millis();accepted_++;buffer_.clear();}}if(!active_)return;uint8_t chunk[1024];while(client_.available()){int n=client_.read(chunk,sizeof chunk);if(n<=0)break;opened_=millis();if(buffer_.size()+n>65536){errors_++;client_.stop();buffer_.clear();active_=false;return;}buffer_.insert(buffer_.end(),chunk,chunk+n);}if(!client_.connected()||millis()-opened_>5000)finish();}
